CREATE OR REPLACE FUNCTION legacy_audit_immutable() RETURNS trigger AS $fn$
BEGIN

  RAISE EXCEPTION 'legacy_events is append-only; % is not permitted', TG_OP
    USING ERRCODE = 'restrict_violation',
          HINT = 'Correct a wrong entry by recording a new one.';
END;
$fn$ LANGUAGE plpgsql;
